/*
 * Prints the mobile method catalog's tables as markdown, straight from the
 * capability table this build actually serves.
 *
 * `AgentPartyMobile/docs/아키텍처/08-메서드-카탈로그.md` is owned by the desktop
 * app member, and its method list is generated by this script rather than kept
 * by hand — a catalog that drifts from the code is worse than none, because the
 * mobile member writes a typed client against it.
 *
 * Run: node scripts/dump-method-catalog.mjs   (after `npm run build`)
 */
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const { methodRoutes } = require(path.join(root, "dist", "main", "api", "methodRoutes.js"));

const DOMAIN_TITLES = {
  app: "앱 · 상태",
  state: "앱 · 상태",
  approval: "승인",
  environment: "환경",
  update: "앱 업데이트",
  settings: "설정",
  appearance: "설정",
  shell: "데스크톱 로컬",
  clipboard: "데스크톱 로컬",
  auth: "인증",
  discord: "Discord 브리지",
  mobile: "모바일 링크 자체",
  models: "모델",
  harness: "모델",
  usage: "사용량",
  tokenUsage: "사용량",
  session: "세션",
  party: "파티",
  member: "멤버",
  layout: "레이아웃",
  workspace: "워크스페이스",
  window: "창 (데스크톱)",
};

const groups = new Map();
for (const route of methodRoutes.routes) {
  const domain = route.name.split(".")[0];
  const title = DOMAIN_TITLES[domain] || domain;
  if (!groups.has(title)) groups.set(title, []);
  groups.get(title).push(route);
}

const lines = [];
for (const [title, routes] of groups) {
  lines.push(`### ${title}`, "", "| 메서드 | HTTP (API.md) | 폰 |", "|---|---|---|");
  for (const route of routes) {
    lines.push(`| \`${route.name}\` | \`${route.http}\` | ${route.remote === false ? "—" : "제공"} |`);
  }
  lines.push("");
}

const remote = methodRoutes.remoteRoutes().length;
lines.push(`총 ${methodRoutes.routes.length}개 · 폰에 제공 ${remote}개 · 데스크톱 전용 ${methodRoutes.routes.length - remote}개`);
console.log(lines.join("\n"));
